```javascript
const axios = require("axios");

async function processTikTokUrl(tiktokUrl) {
  const apiUrl = "https://vidsnap.cloud/wp-admin/admin-ajax.php";
  const commonHeaders = {
    "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
    "Accept": "*/*",
    "X-Requested-With": "XMLHttpRequest"
  };

  try {
    const getInfoResponse = await axios.post(apiUrl, 
      `action=ytdlp_get_info&nonce=89cdce9b5a&url=${encodeURIComponent(tiktokUrl)}`,
      { headers: commonHeaders }
    );

    if (!getInfoResponse.data.success) {
      return { error: "Gagal mendapatkan informasi video." };
    }

    const videoInfo = getInfoResponse.data.data;
    const progressId = "dl_" + Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 17); 

    const getProgressResponse = await axios.post(apiUrl, 
      `action=ytdlp_progress&nonce=89cdce9b5a&progress_id=${progressId}`,
      { headers: commonHeaders }
    );

    if (!getProgressResponse.data.success || getProgressResponse.data.data.status !== "complete") {
      return { error: "Gagal memproses unduhan video." };
    }

    const downloadData = getProgressResponse.data.data;

    return {
      success: true,
      videoDetails: {
        title: videoInfo.title,
        duration: videoInfo.duration,
        thumbnail: videoInfo.thumbnail,
        uploader: videoInfo.uploader,
        formats: videoInfo.formats
      },
      downloadDetails: {
        status: downloadData.status,
        progress: downloadData.progress,
        message: downloadData.message,
        downloadUrl: downloadData.download_url,
        fileName: downloadData.file_name,
        fileSize: downloadData.file_size
      }
    };

  } catch (error) {
    return { error: error.message };
  }
}

const tiktokVideoUrl = "https://vt.tiktok.com/ZS4cWtHop/"; 

processTikTokUrl(tiktokVideoUrl)
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
